steps.script:
var kw = GameState.get_unit("U_PAINBOSS_A").meta.keywords
print("[wp-g3] Painboss keywords attached: ", kw)
return not ("INFANTRY" in kw) and "MOBILE" in kw and "MOUNTED" in kw and not RulesEngine.unit_has_keyword(GameState.get_unit("U_PAINBOSS_A"), "INFANTRY")

var t = tree.root.get_node("Main/DatasheetModal").keywords_text
print("[wp-g3] datasheet (attached): ", t)
return t.contains("MOUNTED") and t.contains("MOBILE") and not t.contains("INFANTRY")

var kw = GameState.get_unit("U_PAINBOSS_A").meta.keywords
print("[wp-g3] Painboss keywords after the bodyguard died: ", kw)
return "INFANTRY" in kw and not ("MOBILE" in kw) and not ("MOUNTED" in kw) and RulesEngine.unit_has_keyword(GameState.get_unit("U_PAINBOSS_A"), "INFANTRY")

var t = tree.root.get_node("Main/DatasheetModal").keywords_text
print("[wp-g3] datasheet (bodyguard destroyed): ", t)
return t.contains("INFANTRY") and not t.contains("MOUNTED") and not t.contains("MOBILE")
